    template<typename T> requires gocpp::GoStruct<T>
    bool divisor::operator==(const T& ref) const
    {
        if (bbb != ref.bbb) return false;
        if (nbits != ref.nbits) return false;
        if (ndigits != ref.ndigits) return false;
        return true;
    }

