    cacheBase10Struct cacheBase10;
    // expWW computes x**y
    nat rec::expWW(golang::big::nat z, Word x, Word y)
    {
        return rec::expNN(gocpp::recv(z), rec::setWord(gocpp::recv(nat(nullptr)), x), rec::setWord(gocpp::recv(nat(nullptr)), y), nullptr, false);
    }

    // construct table of powers of bb*leafSize to use in subdivisions.
    gocpp::slice<divisor> divisors(int m, Word b, int ndigits, Word bb)
    {
        // only compute table when recursive conversion is enabled and x is large
        if(leafSize == 0 || m <= leafSize)
        {
            return nullptr;
        }

        // determine k where (bb**leafSize)**(2**k) >= sqrt(x)
        auto k = 1;
        for(auto words = leafSize; words < (m >> 1) && k < len(cacheBase10.table); words <<= 1)
        {
            k++;
        }

        // reuse and extend existing table of divisors or create new table as appropriate
        // for b == 10, table overlaps with cacheBase10.table
        gocpp::slice<divisor> table = {};
        if(b == 10)
        {
            rec::Lock(gocpp::recv(cacheBase10));
            // reuse old table for this conversion
            table = cacheBase10.table.make_slice(0, k);
        }
        else
        {
            // create new table for this conversion
            table = gocpp::make(gocpp::Tag<gocpp::slice<divisor>>(), k);
        }

        // extend table
        if(table[k - 1].ndigits == 0)
        {
            // add new entries as needed
            nat larger = {};
            for(auto i = 0; i < k; i++)
            {
                if(table[i].ndigits == 0)
                {
                    if(i == 0)
                    {
                        table[0].bbb = rec::expWW(gocpp::recv(nat(nullptr)), bb, Word(leafSize));
                        table[0].ndigits = ndigits * leafSize;
                    }
                    else
                    {
                        table[i].bbb = rec::sqr(gocpp::recv(nat(nullptr)), table[i - 1].bbb);
                        table[i].ndigits = 2 * table[i - 1].ndigits;
                    }

                    // optimization: exploit aggregated extra bits in macro blocks
                    larger = rec::set(gocpp::recv(nat(nullptr)), table[i].bbb);
                    for(; mulAddVWW(larger, larger, b, 0) == 0; )
                    {
                        table[i].bbb = rec::set(gocpp::recv(table[i].bbb), larger);
                        table[i].ndigits++;
                    }

                    table[i].nbits = rec::bitLen(gocpp::recv(table[i].bbb));
                }
            }
        }

        if(b == 10)
        {
            rec::Unlock(gocpp::recv(cacheBase10));
        }

        return table;
    }

